(() => {
  const root=document.getElementById('iwr-night-plotter');
  const canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d');
  const pause=root.querySelector('[data-pause]'),caption=root.querySelector('[data-description]');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const state={style:'broken',mode:'play',paused:reduced.matches,accent:true,gain:.82};
  const names={broken:'Broken Grid',weave:'Step Weave',courier:'Cell Courier',factors:'Factor Constellation',fragments:'Gesture Fragments'};
  const descriptions={
    broken:['Ses eklenerek değil, ızgaradan parçalar eksiltilerek çiziliyor.','Yeni kesikler tarama kafasının arkasında kalıyor; ızgara bir negatif kayda dönüşüyor.'],
    weave:['Köşeli çizgiler birer hücre kayarak kısa süreli desenler örüyor.','Her darbe bir sıraya yeni bir basamak ekliyor; önceki sıralar tutuluyor.'],
    courier:['Beş hücrelik kuryeler, boş bir kafeste mesaj taşıyor.','Kayıt kafası küçük hücre kümeleri bırakıyor; son mesaj kısa süre yerinde kalıyor.'],
    factors:['Küçük sayı kümeleri, ritimle farklı çarpan gruplarına ayrılıyor.','Her darbe bir kümeyi yeniden kuruyor; diğer iki küme son düzenini saklıyor.'],
    fragments:['Ayrı çizgi parçalarını sırayla izleyen küçük bir çizim kafası.','Her hece bir çizik ekliyor; bağımsız izler kısa bir notasyona dönüşüyor.']
  };
  const white='#f1f0e8',amber='#FF0000';
  let w=226,dpr=1,t=2.4,last=0,raf=0,visible=true;
  const clamp=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));
  // Live sound seam: iwrSignal exists only inside the archive gallery. Without it, or with sound off, nothing changes.
  const hearing=()=>typeof iwrSignal!=='undefined'&&iwrSignal.active?iwrSignal:null;
  // Geometry reads audio features. Transport and history have separate clocks.
  const charge=(band='amp',age=0)=>{const s=hearing();return s?clamp(s.bandAt?s.bandAt(band,age):(s[band]??s.level??0)):0;};
  const strike=(kind='kick')=>{const s=hearing();return s?.eventAt?s.eventAt(kind):{n:Math.floor(s?.beat??0),age:s?.[kind+'Age']??30};};
  // Time-driven machines move on the beat and rest between hits; the studies' own dt clamps still apply first.
  const conduct=()=>{const s=hearing();return s?0.25+4.2*s.hit:1;};
  // Whatever time env() is asked for, answer from the last 3.4 s that was actually heard.
  const heardEnv=(s,time)=>{const age=Math.max(0,t-time);return 0.12+0.88*Math.max(s.levelAt(age),s.hitAt(age));};
  const mod=(x,n)=>(x%n+n)%n;
  const fract=x=>x-Math.floor(x);
  const hash=n=>fract(Math.sin(n*127.1+43.7)*43758.5453);
  const accent=()=>state.accent?amber:white;
  // Synthetic numbers and rhythm. No signal classification, pitch, or cellular-automata accuracy claim.
  function env(time) { const s=hearing(); if(s)return clamp(heardEnv(s,time)*state.gain); return clamp((.15+.55*Math.pow(Math.max(0,Math.sin(time*2.7)),6)+.28*Math.pow(Math.max(0,Math.sin(time*6.1+1)),12))*state.gain); }
  function ink(alpha=1,color=white) { ctx.globalAlpha=clamp(alpha);ctx.fillStyle=color;ctx.strokeStyle=color; }
  function rect(x,y,width,height,alpha=1,color=white) { ink(alpha,color);ctx.fillRect(Math.round(x*dpr)/dpr,Math.round(y*dpr)/dpr,width,height); }
  function line(points,alpha=1,color=white) { if(!points.length)return;ink(alpha,color);ctx.lineWidth=1;ctx.lineCap='butt';ctx.lineJoin='miter';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke(); }
  function box(x,y,width,height,alpha=1,color=white) { line([[x,y],[x+width,y],[x+width,y+height],[x,y+height],[x,y]],alpha,color); }
  function broken(time) {
    const pitch=9,n=Math.floor((w-6)/pitch),left=(w-n*pitch)/2,head=mod(time*.19,1),recording=state.mode==='record';
    for(let row=0;row<5;row++)line([[left,4+row*9],[w-left,4+row*9]],.45);
    for(let col=0;col<=n;col++)line([[left+col*pitch,4],[left+col*pitch,40]],.24);
    for(let col=0;col<n;col++) {
      const u=col/n,sample=recording?Math.floor(time*.19)*5+u*5:u*5;
      const a=env(hearing()?time-(1-u)*3.2:sample),rows=Math.round(a*3.6),height=rows*9+4;
      if(!recording||u<head) {
        ctx.clearRect(left+col*pitch+1,22-height/2,pitch-2,height);
        if(rows>1)ctx.clearRect(left+col*pitch-1,22-(rows-1)*4.5,2,(rows-1)*9);
      }
    }
    const x=left+head*n*pitch;
    line([[x,1],[x,5]],1,accent());line([[x,39],[x,43]],1,accent());
    if(recording)line([[x,6],[x,38]],.65,accent());
  }
  function weave(time) {
    const pitch=12,step=hearing()?strike('hat').n:Math.floor(time*3),phase=hearing()?clamp(strike('hat').age/.18):fract(time*3),recording=state.mode==='record',head=mod(step,4);
    for(let row=0;row<4;row++) {
      const shift=recording?mod(Math.floor((step-row+4)/4),2)*pitch/2:mod(step+row,4)*pitch/4;
      const baseline=7+row*10,points=[];
      for(let col=-2;col<w/pitch+2;col++) {
        const x=col*pitch+shift;
        if(recording&&row===head&&x>w*phase)break;
        points.push([x,baseline],[x+pitch/2,baseline],[x+pitch/2,baseline+(hearing()?1+charge(['low','mid','high','amp'][row])*6:5)],[x+pitch,baseline+(hearing()?1+charge(['low','mid','high','amp'][row])*6:5)]);
      }
      line(points,row===head?.95:.5,row===head?accent():white);
    }
  }
  function courier(time) {
    const pitch=4,cols=Math.floor((w-4)/pitch),left=(w-cols*pitch)/2,step=hearing()?strike('hat').n:Math.floor(time*5),recording=state.mode==='record';
    for(let x=0;x<cols;x+=3)for(let y=0;y<9;y+=2)rect(left+x*pitch,5+y*pitch,1,1,.14);
    // Four deliberately hand-authored five-cell states: a courier, not a full Game of Life engine.
    const forms=[[[1,0],[2,1],[0,2],[1,2],[2,2]],[[0,0],[2,0],[1,1],[2,1],[1,2]],[[0,0],[1,0],[2,0],[0,1],[1,2]],[[1,0],[0,1],[1,1],[0,2],[2,2]]];
    if(recording) {
      const positions=Math.max(2,Math.floor(cols/7)),write=mod(Math.floor(step/2),positions);
      for(let p=0;p<=write;p++) {
        const age=write-p,shape=forms[mod(p+Math.floor(step/(positions*2)),4)],x=left+(p*7+2)*pitch;
        shape.forEach(([cx,cy])=>rect(x+cx*pitch,16+cy*pitch,2,2,p===write?1:.38,p===write?accent():white));
      }
      rect(left+(write*7+2)*pitch,8,10,1,1,accent());
    } else {
      for(let k=0;k<3;k++) {
        const x=mod(step+k*Math.floor(cols/3),cols-3),y=[1,3,5][k],shape=forms[hearing()?Math.min(3,Math.floor(charge(['low','mid','high'][k])*3.99)):mod(step+k,4)];
        shape.forEach(([cx,cy])=>rect(left+(x+cx)*pitch,5+(y+cy)*pitch,2,2,.85,k===0?accent():white));
      }
    }
  }
  function factors(time) {
    const groups=3,pitch=w/groups,step=hearing()?strike('note').n:Math.floor(time*1.6),active=mod(step,3),pairs=[[2,3],[2,4],[3,3],[3,4],[3,5],[2,6]],recording=state.mode==='record';
    for(let g=0;g<groups;g++) {
      const tick=recording?step-mod(step-g,3):step+g*2;
      const [a,b]=pairs[hearing()?Math.min(pairs.length-1,Math.floor(charge(['low','mid','high'][g])*pairs.length)):mod(tick,pairs.length)],cx=pitch*(g+.5),r=11,spin=recording?0:time*.22;
      for(let i=0;i<a;i++) {
        const theta=i/a*Math.PI*2-Math.PI/2+spin;
        const x=cx+Math.cos(theta)*r,y=22+Math.sin(theta)*r;
        for(let j=0;j<b;j++) {
          const phi=j/b*Math.PI*2-Math.PI/2;
          const px=x+Math.cos(phi)*4.5,py=y+Math.sin(phi)*4.5;
          rect(px-1,py-1,2,2,g===active?.95:.65,g===active&&i===0?accent():white);
        }
      }
      const total=a*b;
      for(let mark=0;mark<total;mark++)rect(cx-total+mark*2,42,1,1,.25,g===active?accent():white);
      if(recording&&g===active)line([[cx-4,1],[cx+4,1]],1,accent());
    }
  }
  function fragments(time) {
    const count=7,pitch=(w-8)/count,recording=state.mode==='record',phase=hearing()?mod(strike('note').n,count)+Math.min(.999,strike('note').age/.3):mod(time*.85,count+1),active=Math.min(count-1,Math.floor(phase));
    for(let i=0;i<count;i++) {
      const x=4+i*pitch,seed=i+3,y=10+(hearing()?charge('mid',i*.12):hash(seed))*22;
      const points=[[x,y],[x+pitch*.25,clamp(y+8*(hash(seed+5)-.5),4,40)],[x+pitch*.58,clamp(y+16*(hash(seed+12)-.5),4,40)],[x+pitch*.83,clamp(y+18*(hash(seed+3)-.5),4,40)]];
      if(recording&&i>active)continue;
      const progress=i===active?fract(phase):1;
      if(!recording||i<active)line(points,.35);
      if(i===active) {
        const segment=Math.min(2,Math.floor(progress*3)),local=fract(progress*3),from=points[segment],to=points[segment+1];
        const tip=[from[0]+(to[0]-from[0])*local,from[1]+(to[1]-from[1])*local];
        line([...points.slice(0,segment+1),tip],1,accent());
        rect(tip[0]-1,tip[1]-1,3,3,1,accent());
      } else if(recording)line(points,.68);
      if(recording&&i<active)rect(x+pitch*.4,40,2,1,.5);
    }
  }
  const renderers={broken,weave,courier,factors,fragments};
  function draw() { ctx.clearRect(0,0,w,44);ctx.save();ctx.beginPath();ctx.rect(0,0,w,44);ctx.clip();renderers[state.style](t);ctx.restore(); }
  function sync() {
    root.querySelectorAll('[data-style]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.style===state.style)));
    root.querySelectorAll('[data-mode]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.mode===state.mode)));
    const description=descriptions[state.style][state.mode==='record'?1:0];caption.textContent=description;canvas.setAttribute('aria-label',names[state.style]+': '+description);
    root.querySelector('[data-record]').hidden=state.mode!=='record';pause.textContent=state.paused?'Devam et':'Duraklat';pause.setAttribute('aria-pressed',String(state.paused));draw();schedule();
  }
  function resize() { w=Math.max(1,canvas.getBoundingClientRect().width);dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=44*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw(); }
  function schedule() { if(!raf&&!state.paused&&visible&&!document.hidden&&root.isConnected) { last=0;raf=requestAnimationFrame(frame); } }
  function frame(now) { raf=0;if(state.paused||!visible||document.hidden||!root.isConnected)return;if(!last)last=now;const elapsed=now-last;if(elapsed>=1000/30){const heard=hearing();if(heard?.source==='demo')t=heard.songTime;else t+=Math.min(elapsed/1000,.07)*conduct();last=now;draw();}raf=requestAnimationFrame(frame); }
  root.querySelectorAll('[data-style]').forEach(el=>el.addEventListener('click',()=>{state.style=el.dataset.style;sync();}));
  root.querySelectorAll('[data-mode]').forEach(el=>el.addEventListener('click',()=>{state.mode=el.dataset.mode;sync();}));
  pause.addEventListener('click',()=>{state.paused=!state.paused;sync();});
  reduced.addEventListener('change',()=>{state.paused=reduced.matches;sync();});
  document.addEventListener('visibilitychange',schedule);
  new ResizeObserver(resize).observe(canvas);
  new IntersectionObserver(entries=>{const latest=entries.reduce((a,b)=>b.target===root&&(!a||b.time>=a.time)?b:a,null);if(latest){visible=latest.isIntersecting;schedule();}}).observe(root);
  resize();sync();
  if(globalThis.Tweak){const tweak=new Tweak({container:root.querySelector('.nl-phone'),onChange:sync});tweak.addToggle(state,'accent',{label:'Kehribar vurgu'});tweak.addSlider(state,'gain',{label:'Tepki yoğunluğu',min:.3,max:1.2,step:.1});}
})();
